"""A very small JSON pretty printer."""


def pretty(value, indent=2, level=0):
    """Format value as indented JSON text."""
    pad = " " * (indent * level)
    inner = " " * (indent * (level + 1))
    if isinstance(value, dict):
        if not value:
            return "{}"
        parts = []
        for key in sorted(value):
            text = pretty(value[key], indent, level + 1)
            parts.append('%s"%s": %s' % (inner, escape(str(key)), text))
        return "{\n" + ",\n".join(parts) + "\n" + pad + "}"
    if isinstance(value, (list, tuple)):
        if not value:
            return "[]"
        parts = [inner + pretty(v, indent, level + 1) for v in value]
        return "[\n" + ",\n".join(parts) + "\n" + pad + "]"
    if value is None:
        return "null"
    if value is True or value is False:
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return repr(value)
    return '"%s"' % escape(str(value))


def escape(text):
    """Escape a string for JSON."""
    return text.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")
